# -*- coding: utf-8 -*-
"""Science Stage 8 · Unit 3 Ecosystems – Read the lesson (shown below the video) and the lesson document (PDF).
Camday's own text, examples and questions; scope: Cambridge Lower Secondary Science 0893, Stage 8 (8Be.01–8Be.03, 8SIC.02, 8SIC.05)."""
from maths_notes_v4.kit4 import H, I, Y, X, K, L, W, BK, Ex, mcq, grid, num

READ = {}
CARD = lambda title, cards, cols=None: dict({"kind": "sciCards", "title": title, "cards": cards}, **({"cols": cols} if cols else {}))

# =====================================================================================================
# 3.1 Ecosystems and habitats · 8Be.01, 8SIC.02
# =====================================================================================================
READ["3.1"] = L(
    H("A world in a pond",
      "A single pond holds frogs, dragonflies, snails, water weeds and millions of microorganisms – plus water, mud, sunlight and air.",
      "How many different living things might depend on that one pond? How do they depend on each other?"),
    I("Populations, communities and ecosystems",
      "Ecologists describe living things at different levels.",
      table=[["Level", "Meaning", "Example on a savanna"],
             ["**population**", "all the organisms of **one species** in an area", "a herd of zebras"],
             ["**community**", "**all the populations** of different species in an area", "zebras, lions, giraffes, acacia trees, grasses"],
             ["**ecosystem**", "the community **plus** the non-living (physical) factors and all their interactions", "the savanna with its soil, rain, sunlight and temperature"]],
      then=["An ecosystem can be huge – a rainforest – or tiny – a rotting log or a sealed bottle garden."]),
    Y("Which level?",
      grid("s8u03r11", "Population, community or ecosystem?", ["Population", "Community", "Ecosystem"],
           [("all the clownfish on a coral reef", "Population"), ("all the fish, corals and algae on the reef", "Community"), ("the reef with its water, light and temperature", "Ecosystem"),
            ("all the oak trees in a wood", "Population")],
           "One species, all species, or living + non-living?", "One species → population; all species → community; plus non-living factors → ecosystem.")),
    I("Ecosystems and habitats",
      "Earth has many kinds of ecosystem: forests, grasslands, deserts, freshwater (ponds, rivers, lakes) and saltwater (oceans, coral reefs, mangroves).",
      then=["Each ecosystem contains many **habitats**. A **habitat** is the place where an organism lives. A deer's habitat is the forest; a beetle's habitat may be the bark of a single tree."]),
    I("Predict, watch, explain: where do woodlice go?",
      "Twelve woodlice are put in the middle of a **choice chamber**: one side damp and dark, the other dry and light. After ten minutes, ten are on the damp, dark side.",
      then=["Woodlice lose water easily through their body covering, so they survive best in damp places such as under logs and stones. Moving away from light also helps them hide from predators. This behaviour is an **adaptation**."]),
    I("Data: a quadrat survey",
      "A class placed square frames (**quadrats**) at random in three parts of the school field and counted the dandelions in each.",
      fig={"kind": "barchart", "labels": ["full sun", "part shade", "deep shade"], "values": [12, 7, 1.5], "ymax": 14, "step": 2, "ylabel": "mean dandelions per quadrat", "xlabel": "area"},
      then=["The more light, the more dandelions – **light** is the non-living factor that matters most here.",
            "Quadrats are placed **at random** and **many** are used so the sample is fair and represents the whole area."]),
    I("Adaptations",
      "**Adaptations** are features that help an organism survive in its habitat.",
      table=[["Organism", "Physical adaptations", "Behavioural adaptations"],
             ["camel", "fat stored in hump; wide feet for sand; long eyelashes against dust", "rests in the heat of the day"],
             ["dolphin", "streamlined body, blowhole, flippers, blubber", "lives in groups (pods); communicates; uses echolocation"],
             ["cactus", "spines instead of leaves (less water loss), thick stem stores water, long roots", "—"],
             ["Arctic fox", "thick white winter fur, small ears", "stores food for winter"]]),
    I("Seed banks",
      "About two in five plant species are at risk of extinction. **Seed banks** store seeds of many species so they can be grown again if wild plants are lost.",
      then=["Seeds are dried and kept dark and cold (about −20 °C) so they do not germinate, and every packet is labelled with the variety and where it was collected. Some vaults are built inside mountains, safe from floods and earthquakes. They protect **biodiversity** and future food crops."]),
    K("Key points",
      "**Population**: one species; **community**: all species; **ecosystem**: community + non-living factors.",
      "A **habitat** is where an organism lives; ecosystems contain many habitats.",
      "Quadrats placed at random measure how organisms are spread.",
      "**Adaptations** (physical and behavioural) help survival. Seed banks protect plant biodiversity."),
    book=BK(
        [("population", "all the organisms of one species in an area"), ("community", "all the populations in an area"), ("ecosystem", "a community and its non-living surroundings"),
         ("habitat", "the place where an organism lives"), ("adaptation", "a feature that helps an organism survive"), ("quadrat", "a square frame used to sample organisms"),
         ("seed bank", "a store of seeds kept to protect plant species")],
        [], [],
        [Ex("Explain the difference between a population and a community.", ans="A population is one species; a community is all the populations of different species in an area."),
         Ex("Give two physical and one behavioural adaptation of a camel.", ans="physical: hump stores fat, wide feet, long eyelashes; behavioural: rests in the heat of the day"),
         Ex("Why are quadrats placed at random, and why are many used?", ans="To avoid bias and get a sample that represents the whole area."),
         Ex("Why are seeds in a seed bank kept dry, dark and cold?", ans="So they do not germinate and stay alive for many years."),
         Ex("Suggest why woodlice moving to dark, damp places helps them survive.", ans="They lose less water and are hidden from predators.", think=True)],
        ["describe populations, communities and ecosystems", "explain what a habitat is", "use quadrat data", "describe adaptations", "explain why seed banks are important"],
        look=["population, community, ecosystem", "the adaptations table"],
        note="Read it after the video: ecosystems, habitats, adaptations and seed banks (answers at the back)."),
)

# =====================================================================================================
# 3.2 Human impact on ecosystems · 8Be.02, 8Be.03, 8SIC.05
# =====================================================================================================
READ["3.2"] = L(
    H("One species changes everything",
      "No other species has changed the Earth as much as humans: we clear forests, build cities, fish the oceans and move animals around the world.",
      "Name one way people harm ecosystems and one way they help them."),
    I("Habitat destruction",
      "Clearing land for farms, buildings, roads and mines destroys habitats – organisms lose their food and shelter.",
      then=["**Deforestation** removes trees that are **carbon sinks** (they absorb more carbon dioxide than they release), so it also adds to climate change.",
            "Roads and farms can split a large habitat into small pieces (**habitat fragmentation**), making it harder for animals to find food, water and mates."]),
    I("Overexploitation and invasive species",
      "**Overexploitation** means taking too many organisms from the wild – for example **overfishing** or overhunting – faster than they can reproduce.",
      then=["An **invasive species** is a non-native species that spreads and harms an ecosystem. Example: the Nile perch, put into Lake Victoria as food, ate hundreds of native fish species. Rats and cats carried on ships have wiped out many island birds.",
            "Good news: protecting areas and **re-introducing** lost species (such as wolves in Yellowstone) can help ecosystems recover."]),
    Y("Name the threat",
      grid("s8u03r21", "Which human impact is described?", ["Habitat destruction", "Overexploitation", "Invasive species", "Pollution"],
           [("a mangrove is cleared to build a shrimp farm", "Habitat destruction"), ("sharks are caught faster than they breed", "Overexploitation"),
            ("cane toads brought to Australia spread and poison native predators", "Invasive species"), ("an oil spill coats seabirds", "Pollution")],
           "Clearing, over-taking, a newcomer, or harmful substances?", "Clearing = habitat destruction; over-catching = overexploitation; a harmful newcomer = invasive species; oil = pollution.")),
    I("Pollution",
      "Pollution harms land, air and water.",
      table=[["Type", "Sources", "Harm"],
             ["land", "litter, plastics, chemicals, landfill sites", "poisons soil; rotting rubbish releases methane"], ["air", "factory smoke, vehicle exhausts, burning", "acid rain, breathing problems"],
             ["water", "fertilisers, pesticides, sewage, factory waste, oil spills, plastic", "algal blooms, poisoned wildlife, microplastics in food chains"]]),
    I("Predict, watch, explain: fertiliser in pond water",
      "Two jars of the same pond water stand in sunlight for two weeks; a few drops of fertiliser are added to one. That jar turns bright green with algae.",
      fig={"kind": "sciFlow", "title": "How fertiliser kills fish", "steps": [{"t": "Fertiliser washes into a lake"}, {"t": "Algae grow fast", "d": "an algal bloom"},
                                                                             {"t": "Light is blocked", "d": "water plants die"}, {"t": "Bacteria decompose", "d": "they use up the oxygen"},
                                                                             {"t": "Fish die", "d": "no oxygen"}]}),
    I("Data: mercury along a food chain",
      "Typical amounts of mercury in a polluted lake food chain (parts per million):",
      fig={"kind": "barchart", "labels": ["plankton", "small fish", "large fish", "fish-eating bird"], "values": [0.04, 0.5, 2, 16], "ymax": 16, "step": 4, "ylabel": "mercury (ppm)", "xlabel": "organism"},
      then=["Mercury cannot be broken down or excreted, so it builds up in each organism (**bioaccumulation**).",
            "Each animal eats many of the organisms below it, so the amount gets bigger at each step up the food chain (**biomagnification**). The top predator has the most – people who eat contaminated fish can get mercury poisoning."]),
    Y("Biomagnification",
      mcq("s8u03r22", "Why does the bird at the top of the food chain contain the most mercury?",
          [("It eats many fish, each containing mercury that cannot be excreted.", True, "Yes – mercury from every fish builds up in the bird."),
           ("It drinks the most lake water.", False, "Most comes through its food."), ("Birds make their own mercury.", False, "Mercury comes from pollution."),
           ("It is the oldest organism.", False, "Age is not the main reason.")],
          "Think about how much each animal eats.", "Each level eats many of the level below, so the mercury is concentrated.")),
    K("Key points",
      "Human impacts: **habitat destruction** (deforestation, fragmentation), **overexploitation**, **invasive species**, **pollution**.",
      "Fertiliser causes algal blooms; decomposing algae use up oxygen and fish die.",
      "Toxic substances such as mercury **bioaccumulate** and are **biomagnified** along food chains.",
      "Protection and re-introductions can help ecosystems recover."),
    book=BK(
        [("deforestation", "cutting down large areas of forest"), ("overexploitation", "taking too many organisms from the wild"), ("invasive species", "a non-native species that spreads and causes harm"),
         ("algal bloom", "a rapid growth of algae in water"), ("bioaccumulation", "a toxic substance building up in an organism"),
         ("biomagnification", "a toxic substance becoming more concentrated up a food chain")],
        [], [],
        [Ex("Give two effects of deforestation.", ans="loss of habitats / biodiversity; more carbon dioxide in the air (climate change); soil erosion"),
         Ex("Explain how fertiliser running into a lake can kill fish.", ans="Algae grow fast and block light; plants die; bacteria decomposing them use up the oxygen; fish suffocate."),
         Ex("Use the chart: how many times more mercury is in the bird than in the large fish?", ans="16 ÷ 2 = 8 times"),
         Ex("Quick quiz.", ("Population or community: all the frogs in a pond?", "population"), ("Give one physical adaptation of a dolphin.", "e.g. streamlined body, blowhole, blubber"),
            ("What is an invasive species?", "a non-native species that spreads and harms an ecosystem"), ("What is biomagnification?", "a toxin becoming more concentrated up a food chain")),
         Ex("Suggest two ways a community could reduce the harm it does to a nearby river.", ans="e.g. use less fertiliser, treat sewage, stop litter, plant trees along the banks.", think=True)],
        ["explain habitat destruction, overexploitation and invasive species", "describe types of pollution", "explain algal blooms", "explain bioaccumulation and biomagnification"],
        look=["how fertiliser kills fish", "the mercury chart"],
        note="Read it after the video: human impacts, pollution and biomagnification, plus a quick quiz (answers at the back)."),
)
